INSERT INTO `wp_postmeta` VALUES (3,5,'_wp_attached_file','woocommerce-placeholder.webp'),(4,5,'_wp_attachment_metadata','a:6:{s:5:\"width\";i:1200;s:6:\"height\";i:1200;s:4:\"file\";s:28:\"woocommerce-placeholder.webp\";s:8:\"filesize\";i:9892;s:5:\"sizes\";a:3:{s:21:\"woocommerce_thumbnail\";a:6:{s:4:\"file\";s:36:\"woocommerce-placeholder-300x300.webp\";s:5:\"width\";i:300;s:6:\"height\";i:300;s:9:\"mime-type\";s:10:\"image/webp\";s:8:\"filesize\";i:1362;s:9:\"uncropped\";b:0;}s:29:\"woocommerce_gallery_thumbnail\";a:5:{s:4:\"file\";s:36:\"woocommerce-placeholder-100x100.webp\";s:5:\"width\";i:100;s:6:\"height\";i:100;s:9:\"mime-type\";s:10:\"image/webp\";s:8:\"filesize\";i:430;}s:18:\"woocommerce_single\";a:5:{s:4:\"file\";s:36:\"woocommerce-placeholder-600x600.webp\";s:5:\"width\";i:600;s:6:\"height\";i:600;s:9:\"mime-type\";s:10:\"image/webp\";s:8:\"filesize\";i:3162;}}s:10:\"image_meta\";a:13:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:0:\"\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:17:\"created_timestamp\";s:1:\"0\";s:9:\"copyright\";s:0:\"\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";s:1:\"0\";s:8:\"keywords\";a:0:{}s:3:\"alt\";s:0:\"\";}}'),(5,16,'_hala_seed','wc-cart|en'),(6,18,'_hala_seed','wc-checkout|en'),(7,20,'_hala_seed','wc-myaccount|en'),(8,22,'_wp_page_template','front-page.php'),(9,22,'_hala_seed','page-home|ar'),(10,24,'_wp_page_template','front-page.php'),(11,24,'_hala_seed','page-home|en'),(12,26,'_wp_page_template','page-about.php'),(13,26,'_hala_seed','page-about|ar'),(14,28,'_wp_page_template','page-about.php'),(15,28,'_hala_seed','page-about|en'),(16,30,'_hala_seed','page-blog|ar'),(17,32,'_hala_seed','page-blog|en'),(18,34,'_wp_page_template','page-contact.php'),(19,34,'_hala_seed','page-contact|ar'),(20,36,'_wp_page_template','page-contact.php'),(21,36,'_hala_seed','page-contact|en'),(22,38,'_wp_page_template','page-faq.php'),(23,38,'_hala_seed','page-faq|ar'),(24,40,'_wp_page_template','page-faq.php'),(25,40,'_hala_seed','page-faq|en'),(26,42,'_wp_page_template','page-policy.php'),(27,42,'_hala_seed','page-terms|ar'),(28,42,'hero_title','سياسة الاسترجاع والإستبدال'),(29,42,'_hero_title','field_policy_hero_title'),(30,42,'updated','26 أكتوبر 2026'),(31,42,'_updated','field_policy_updated'),(32,42,'closing',''),(33,42,'_closing','field_policy_closing'),(34,42,'sections_0_heading','استرجاع واستبدال الكتب المطبوعة'),(35,42,'_sections_0_heading','field_policy_sections_heading'),(36,42,'sections_0_body','<ul><li>يحق للعميل طلب استبدال أو استرجاع الكتاب المطبوع في حال وجود عيب طباعي أو تلف في النسخة خلال 7 أيام من تاريخ الاستلام.</li><li>يُشترط أن يكون الكتاب بحالته الأصلية تماماً، وغير مستخدم، وبغلافه الأصلي.</li><li>في حال كان التلف ناتجاً عن خطأ من قِبلنا أو شركة الشحن، يتحمل الموقع تكلفة الاستبدال والشحن بالكامل.</li></ul>'),(37,42,'_sections_0_body','field_policy_sections_body'),(38,42,'sections_1_heading','الكتب الرقمية والنسخ الإلكترونية'),(39,42,'_sections_1_heading','field_policy_sections_heading'),(40,42,'sections_1_body','<ul><li>نظراً لطبيعة الكتب والملفات الرقمية (النسخ الإلكترونية أو روابط التحميل)، لا يمكن استرجاعها أو استبدالها بعد إتمام عملية الشراء وتفعيل التحميل، حرصاً على حقوق الملكية الفكرية.</li></ul>'),(41,42,'_sections_1_body','field_policy_sections_body'),(42,42,'sections','2'),(43,42,'_sections','field_policy_sections'),(44,44,'_wp_page_template','page-policy.php'),(45,44,'_hala_seed','page-terms|en'),(46,44,'hero_title','Refund & Exchange Policy'),(47,44,'_hero_title','field_policy_hero_title'),(48,44,'updated','26 October 2026'),(49,44,'_updated','field_policy_updated'),(50,44,'closing',''),(51,44,'_closing','field_policy_closing'),(52,44,'sections_0_heading','Returns and exchanges of printed books'),(53,44,'_sections_0_heading','field_policy_sections_heading'),(54,44,'sections_0_body','<ul><li>Customers may request an exchange or return of a printed book if it has a printing defect or is damaged within 7 days of receipt.</li><li>The book must be in its original condition, unused and in its original cover.</li><li>If the damage was caused by our error or the courier, the site bears the full cost of exchange and shipping.</li></ul>'),(55,44,'_sections_0_body','field_policy_sections_body'),(56,44,'sections_1_heading','Digital books and electronic copies'),(57,44,'_sections_1_heading','field_policy_sections_heading'),(58,44,'sections_1_body','<ul><li>Due to the nature of digital books and files (electronic copies or download links), they cannot be returned or exchanged once the purchase is complete and the download is activated, to protect intellectual property rights.</li></ul>'),(59,44,'_sections_1_body','field_policy_sections_body'),(60,44,'sections','2'),(61,44,'_sections','field_policy_sections'),(62,46,'_wp_page_template','page-policy.php'),(63,46,'_hala_seed','page-privacy|ar'),(64,46,'hero_title','سياسة الخصوصية'),(65,46,'_hero_title','field_policy_hero_title'),(66,46,'updated','26 أكتوبر 2026'),(67,46,'_updated','field_policy_updated'),(68,46,'closing','بتصفحك لموقع د. هالة مصطفى جمعة أو استخدامك لخدماتنا، فإنك توافق على سياسة الخصوصية هذه وتقر بأنك قرأتها وفهمتها.'),(69,46,'_closing','field_policy_closing'),(70,46,'sections_0_heading','المعلومات التي نقوم بجمعها'),(71,46,'_sections_0_heading','field_policy_sections_heading'),(72,46,'sections_0_body','<p><strong>نقوم بجمع المعلومات التالية عند تفاعلك مع الموقع:</strong></p><ul><li>الاسم الكامل</li><li>بيانات التواصل مثل البريد الإلكتروني ورقم الهاتف (عند الاشتراك في النشرة البريدية أو التواصل للاستفسارات).</li><li>المعلومات المقدمة عبر نماذج التواصل أو طلبات اقتناء الكتب والمقالات.</li><li>موقع الزائر الجغرافي وتقنيات التصفح العامة لتحسين جودة محتوى الموقع.</li></ul>'),(73,46,'_sections_0_body','field_policy_sections_body'),(74,46,'sections_1_heading','استخدام المعلومات'),(75,46,'_sections_1_heading','field_policy_sections_heading'),(76,46,'sections_1_body','<p><strong>يتم استخدام المعلومات الشخصية التي نجمعها للأغراض التالية:</strong></p><ul><li>إرسال الإشعارات والتحديثات عند صدور كتب أو مقالات جديدة.</li><li>التواصل مع الزوار للرد على الاستفسارات والمراسلات الأكاديمية أو المهنية.</li><li>تحسين مستوى الخدمات المعرفية وتطوير محتوى الموقع بناءً على اهتمامات الزوار.</li><li>إرسال النشرة البريدية الإخبارية (للراغبين في متابعة كل جديد).</li></ul>'),(77,46,'_sections_1_body','field_policy_sections_body'),(78,46,'sections_2_heading','ملفات تعريف الارتباط (Cookies)'),(79,46,'_sections_2_heading','field_policy_sections_heading'),(80,46,'sections_2_body','<ul><li>قد يستخدم موقعنا ملفات تعريف الارتباط لتحسين تجربة التصفح وتخصيص المحتوى. يمكنكم تعطيل هذه الملفات في أي وقت من إعدادات المتصفح الخاص بكم.</li></ul>'),(81,46,'_sections_2_body','field_policy_sections_body'),(82,46,'sections','3'),(83,46,'_sections','field_policy_sections'),(84,48,'_wp_page_template','page-policy.php'),(85,48,'_hala_seed','page-privacy|en'),(86,48,'hero_title','Privacy Policy'),(87,48,'_hero_title','field_policy_hero_title'),(88,48,'updated','26 October 2026'),(89,48,'_updated','field_policy_updated'),(90,48,'closing','By browsing Dr. Hala Mostafa Gomaa\'s site or using our services, you agree to this privacy policy and acknowledge that you have read and understood it.'),(91,48,'_closing','field_policy_closing'),(92,48,'sections_0_heading','Information we collect'),(93,48,'_sections_0_heading','field_policy_sections_heading'),(94,48,'sections_0_body','<p><strong>We collect the following information when you interact with the site:</strong></p><ul><li>Full name</li><li>Contact details such as email and phone number (when subscribing to the newsletter or contacting us with enquiries).</li><li>Information provided through contact forms or requests for books and articles.</li><li>Visitor geographic location and general browsing technologies to improve the quality of site content.</li></ul>'),(95,48,'_sections_0_body','field_policy_sections_body'),(96,48,'sections_1_heading','How we use information'),(97,48,'_sections_1_heading','field_policy_sections_heading'),(98,48,'sections_1_body','<p><strong>The personal information we collect is used for the following purposes:</strong></p><ul><li>Sending notifications and updates when new books or articles are published.</li><li>Communicating with visitors to answer academic or professional enquiries.</li><li>Improving knowledge services and developing site content based on visitors\' interests.</li><li>Sending the email newsletter (for those who wish to follow every update).</li></ul>'),(99,48,'_sections_1_body','field_policy_sections_body'),(100,48,'sections_2_heading','Cookies'),(101,48,'_sections_2_heading','field_policy_sections_heading'),(102,48,'sections_2_body','<ul><li>Our site may use cookies to improve your browsing experience and personalise content. You can disable them at any time in your browser settings.</li></ul>'),(103,48,'_sections_2_body','field_policy_sections_body'),(104,48,'sections','3'),(105,48,'_sections','field_policy_sections'),(106,22,'hero_on','1'),(107,22,'_hero_on','field_home_hero_on'),(108,22,'exp_on','1'),(109,22,'_exp_on','field_home_exp_on'),(110,22,'books_on','1'),(111,22,'_books_on','field_home_books_on'),(112,22,'ann_on','1'),(113,22,'_ann_on','field_home_ann_on'),(114,22,'res_on','1'),(115,22,'_res_on','field_home_res_on'),(116,22,'art_on','1'),(117,22,'_art_on','field_home_art_on'),(118,22,'vis_on','1'),(119,22,'_vis_on','field_home_vis_on'),(120,22,'bcta_on','1'),(121,22,'_bcta_on','field_home_bcta_on'),(122,22,'nl_on','1'),(123,22,'_nl_on','field_home_nl_on'),(124,50,'_wp_attached_file','2026/11/portrait.jpg'),(125,50,'_wp_attachment_metadata','a:6:{s:5:\"width\";i:800;s:6:\"height\";i:800;s:4:\"file\";s:20:\"2026/11/portrait.jpg\";s:8:\"filesize\";i:48001;s:5:\"sizes\";a:10:{s:6:\"medium\";a:5:{s:4:\"file\";s:20:\"portrait-300x300.jpg\";s:5:\"width\";i:300;s:6:\"height\";i:300;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:9609;}s:9:\"thumbnail\";a: